def transform(wb):
    ws = wb["Sheet1"]
    start = None
    for r in range(1, ws.max_row + 1):
        v = ws.cell(row=r, column=1).value
        if v is not None:
            s = str(v)
            if s.startswith("400-") and s.endswith("-A"):
                start = r
                break
    if start is not None:
        end = ws.max_row + 1
        for r in range(start + 1, ws.max_row + 1):
            v = ws.cell(row=r, column=1).value
            if v is not None:
                s = str(v)
                if s.startswith("400-"):
                    end = r
                    break
        if end > start:
            ws.delete_rows(start, end - start)
